import{_ as o,o as t,c as i,a7 as d}from"./chunks/framework.DUCm5Bu5.js";const h=JSON.parse('{"title":"商店管理","description":"透過管理介面瀏覽商店總目錄、管理來源並把伺服器套件下載到暫存區。","frontmatter":{"title":"商店管理","description":"透過管理介面瀏覽商店總目錄、管理來源並把伺服器套件下載到暫存區。","updated":"2026-10-25T00:00:00.000Z"},"headers":[],"relativePath":"zh-tw/guides/store.md","filePath":"zh-tw/guides/store.md"}'),a={name:"zh-tw/guides/store.md"};function c(r,e,s,n,l,u){return t(),i("div",null,[...e[0]||(e[0]=[d('<h1 id="store-management" tabindex="-1">商店管理 <a class="header-anchor" href="#store-management" aria-label="Permalink to &quot;商店管理 {#store-management}&quot;">​</a></h1><p>商店是用於分發伺服器套件的管理介面。它瀏覽已設定的目錄來源、預覽 GitHub 發行中繼資料，並把伺服器套件下載到經過驗證的暫存區。本頁的一切都受系統管理員工作階段保護：透過 WebUI（或 <code>POST /api/auth/login</code>）登入後，每個商店請求都需要該工作階段 Cookie。商店<strong>只做暫存，不做其他任何事</strong>：任何商店動作都不會解壓縮封存檔、載入模組或替換應用程式路徑。一次完成的下載是經過驗證的檔案清單，而不是已安裝的模組。</p><p>商店隨核心捆綁包發布（<code>distribution.sources</code>、<code>distribution.plans</code>、<code>distribution.packages</code> 與 <code>distribution.jobs</code> 四列），<code>kr-812</code>、<code>management</code> 與 <code>all</code> profile 均包含它們。暫存預設落在 <code>data/distribution-staging</code>，由獨佔的持有者鎖保護；歷史頁預設 20 筆；可用空間保留預設為零。來源儲存在 <code>data/distribution-sources.json</code>——把 <code>state_path</code> 留空會使來源清單變為唯讀。</p><h2 id="sources" tabindex="-1">來源 <a class="header-anchor" href="#sources" aria-label="Permalink to &quot;來源 {#sources}&quot;">​</a></h2><p>來源卡片按營運者順序列出已設定的目錄來源，順序很重要：預設選中第一個能提供目錄的來源。每列有 ID、顯示名稱、種類（<code>http</code>、<code>alist</code> 或 <code>github</code>）、根 URL 與目錄路徑。URL 不攜帶憑證、查詢或片段；根路徑必須以 <code>/</code> 結尾。可以上下移動、新增與刪除列，然後一次儲存整個清單。</p><p>儲存使用樂觀修訂：編輯器在開啟時記錄設定修訂，儲存時一併送回。如果期間另一位系統管理員儲存過，儲存會以 <code>source_revision_conflict</code> 被拒絕，對話方塊保持開啟，供你核對後重新套用。GitHub 鏡像支援尚未實作：啟用 <code>use_github_mirror</code> 會讓 distribution 列在啟動時失敗，而不是假裝加速下載。</p><h2 id="browsing" tabindex="-1">瀏覽總目錄 <a class="header-anchor" href="#browsing" aria-label="Permalink to &quot;瀏覽總目錄 {#browsing}&quot;">​</a></h2><p>總目錄頁把所有來源的套件合併為一張按套件識別去重的卡片清單。篩選器可以選擇全部來源或單一來源；重新整理會重新讀取每個總目錄（或單一來源的）。某個來源失敗時絕不會靜默消失——它的失敗原因（<code>source_timeout</code>、<code>source_unavailable</code> 或 <code>catalog_invalid</code>）會列在卡片上方，健康的來源照常顯示。</p><p>同一總目錄中出現同一套件的多個發行時，以發行者最高的 <code>revision</code> 為準；並列——或多發行群的修訂全部未設定——是設定錯誤，而不是猜測。面向用戶端的套件可見，但只有伺服器目標可以下載：選取它會顯示「用戶端模組僅提供預覽」。</p><h2 id="github-repositories" tabindex="-1">GitHub 儲存庫 <a class="header-anchor" href="#github-repositories" aria-label="Permalink to &quot;GitHub 儲存庫 {#github-repositories}&quot;">​</a></h2><p>GitHub 來源從儲存庫讀取目錄文件。儲存庫發行表單預覽一個儲存庫的最新穩定發行——或明確指定的標籤——及其附件：草稿與預發行會被拒絕，每個附件 URL 必須屬於所請求的儲存庫與標籤，只有當 GitHub 為附件發布了 <code>sha256:</code> 摘要時，附件才攜帶發行者 SHA-256。預覽只提供中繼資料；它不會下載任何內容。</p><p><code>github_repository</code> 與 <code>github_tag</code> 欄位屬於總目錄 schema 3。它們在伺服器與啟動器的嚴格總目錄讀取器上都可用，但這是暫行的協調格式，不是已發布的共享合約——在與啟動器發行版本就格式達成共識之前，不要把正式總目錄改發為 schema 3。儲存庫附件只有攜帶該發行者摘要才能下載；否則下載按鈕保持停用，因為下載執行的逐位元組驗證沒有可比對的對象。</p><h2 id="staging" tabindex="-1">下載到暫存區 <a class="header-anchor" href="#staging" aria-label="Permalink to &quot;下載到暫存區 {#staging}&quot;">​</a></h2><p>下載伺服器套件是三步流程，每一步都釘住所顯示的內容：</p><ol><li><strong>選取</strong>卡片上的一個下載供給。每個供給都攜帶選取指紋——對已設定來源與該供給精確內容的 SHA-256——以及它讀取自的總目錄位元組的 SHA-256。</li><li><strong>規劃</strong>下載。計畫會針對這些釘住重新驗證來源、總目錄、發行與附件；來源或供給發生變化時，以 <code>distribution_source_changed</code> 或 <code>distribution_selection_changed</code> 拒絕，而不是下載別的東西。</li><li><strong>受理</strong>工作。工作在串流傳輸時驗證每個檔案的大小與 SHA-256，把資料區塊以不透明形式保存在暫存根下，並報告階段（<code>preparing</code>、<code>transferring</code>、<code>staged</code>）。下載面板輪詢進度、按需對已暫存工作做完整回讀驗證、取消進行中的工作，並刪除終態工作及其暫存內容。</li></ol><p>通過驗證只說明當時暫存卷裡有什麼。它不授予任何安裝授權；磁碟上的後續變化要靠再次驗證發現，而不是被預設可信。</p><h2 id="client-plugin-policy" tabindex="-1">用戶端模組啟動策略 <a class="header-anchor" href="#client-plugin-policy" aria-label="Permalink to &quot;用戶端模組啟動策略 {#client-plugin-policy}&quot;">​</a></h2><p>伺服器完成安裝後，商店頁面還可以編輯用戶端模組啟動策略：按識別設定選用的精確用戶端組建與建議、必需或停用狀態（必需與停用不得重疊）。儲存需要系統管理員工作階段之外的 <code>webui.settings.client_plugins</code> 權限，且僅在伺服器已安裝並就緒時被接受，儲存後會重新執行設定套用。這些規則設定的是相容的啟動器——用戶端二進位檔不會安裝在伺服器上，這些規則也不能證明用戶端完整性。格式見<a href="./plugins#client-plugin-policy">用戶端模組啟動策略</a>。</p><h2 id="administration-api" tabindex="-1">管理 API <a class="header-anchor" href="#administration-api" aria-label="Permalink to &quot;管理 API {#administration-api}&quot;">​</a></h2><p>WebUI 呼叫的端點與營運者指令碼可用的相同。以下所有路徑都需要系統管理員工作階段 Cookie；非 GET 請求還需要 <code>X-BFF-Request: 1</code> 標頭與同來源的 <code>Origin</code>。</p><table tabindex="0"><thead><tr><th>方式與路徑</th><th>用途</th></tr></thead><tbody><tr><td><code>GET/PUT /api/distribution/v1/sources</code></td><td>讀取或攜帶修訂替換來源清單。</td></tr><tr><td><code>POST /api/distribution/v1/repository-release</code></td><td>預覽一個 GitHub 發行（僅中繼資料）。</td></tr><tr><td><code>GET /api/distribution/v1/catalog?sourceId=</code></td><td>合併後的總目錄快照，或單一來源的。</td></tr><tr><td><code>POST /api/distribution/v1/plans</code> · <code>/validate</code> · <code>DELETE</code></td><td>釘住、複查與釋放一個選取。</td></tr><tr><td><code>POST /api/distribution/v1/plans/{id}/files</code></td><td>驗證資訊清單並列出裝載檔案。</td></tr><tr><td><code>GET/POST /api/distribution/v1/jobs</code> · <code>GET /{id}</code></td><td>歷史分頁與受理（202，帶 <code>Location</code> 標頭）。</td></tr><tr><td><code>POST /api/distribution/v1/jobs/{id}/cancel</code> · <code>/verify</code> · <code>DELETE</code></td><td>取消、驗證暫存回讀，或移除終態工作。</td></tr></tbody></table><p>穩定的錯誤碼（<code>source_revision_conflict</code>、<code>distribution_selection_changed</code>、<code>distribution_job_not_staged</code>、<code>repository_rate_limited</code> 等）說明失敗原因；HTTP 狀態區分錯誤請求（400）、過期的釘住（409）、上游問題（502/504）與儲存或設定問題（503）。</p><h2 id="limits" tabindex="-1">商店不做什麼 <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;商店不做什麼 {#limits}&quot;">​</a></h2><ul><li>不安裝、不啟用：沒有任何路由會解壓、載入或重新啟動任何東西。下載不是安裝，持久的意圖也不是執行中的功能。</li><li>GitHub 鏡像按設計直接失敗，而不是假裝可用。</li><li>跨來源的資訊清單參照會被拒絕（「尚不支援」）。</li><li>啟動器目前不消費任何這些內容：它不讀取商店總目錄；在其下載引擎發布之前，用戶端預設只是對外展示的資料。</li></ul>',24)])])}const b=o(a,[["render",c]]);export{h as __pageData,b as default};
